import csv
def save_csv(filename, headers, data_rows):
    with open(filename, 'w', newline='', encoding='utf-8') as f:
        if data_rows and isinstance(data_rows[0], dict):
            writer = csv.DictWriter(f, fieldnames=headers)
            writer.writeheader()
            for row in data_rows:
                if set(row.keys()) != set(headers):
                    raise ValueError("Dictionary keys mismatch headers")
                writer.writerow(row)
        else:
            writer = csv.writer(f)
            writer.writerow(headers)
            for row in data_rows:
                if len(row) != len(headers):
                    raise ValueError("Row length mismatch headers")
                writer.writerow(row)
